parameters.value:
={{ {
  "project": {
    "key": $json.issue.fields.project.key
  },
  "parent": {
    "key": $json.issue.key
  },
  "summary": "🔒 Security Review: " + $json.issue.fields.summary,
  "description": {
    "type": "doc",
    "version": 1,
    "content": [
      {
        "type": "paragraph",
        "content": [
          {
            "type": "text",
            "text": "Security review task for: " + $json.issue.fields.summary
          }
        ]
      },
      {
        "type": "paragraph",
        "content": [
          {
            "type": "text",
            "text": "📋 Review Checklist:"
          }
        ]
      },
      {
        "type": "bulletList",
        "content": [
          {
            "type": "listItem",
            "content": [
              {
                "type": "paragraph",
                "content": [
                  {
                    "type": "text",
                    "text": "SAST scan completed"
                  }
                ]
              }
            ]
          },
          {
            "type": "listItem",
            "content": [
              {
                "type": "paragraph",
                "content": [
                  {
                    "type": "text",
                    "text": "Security vulnerabilities assessed"
                  }
                ]
              }
            ]
          },
          {
            "type": "listItem",
            "content": [
              {
                "type": "paragraph",
                "content": [
                  {
                    "type": "text",
                    "text": "Risk level evaluated"
                  }
                ]
              }
            ]
          },
          {
            "type": "listItem",
            "content": [
              {
                "type": "paragraph",
                "content": [
                  {
                    "type": "text",
                    "text": "Remediation plan created"
                  }
                ]
              }
            ]
          }
        ]
      }
    ]
  },
  "issuetype": {
    "name": "Sub-task"
  },
  "assignee": {
    "accountId": "{{ $vars.SECURITY_TEAM_LEAD_ID }}" || "auto"
  },
  "labels": ["security-review", "sast-pending", "auto-created"],
  "priority": {
    "name": $json.issue.fields.priority?.name || "Medium"
  }
} }}

={{ {
  "type": "doc",
  "version": 1,
  "content": [
    {
      "type": "paragraph",
      "content": [
        {
          "type": "text",
          "text": "🔍 SAST Scan Results - " + $('Process SAST Data').item.json.scanTool,
          "marks": [
            {
              "type": "strong"
            }
          ]
        }
      ]
    },
    {
      "type": "paragraph",
      "content": [
        {
          "type": "text",
          "text": "Scan completed: " + new Date($('Process SAST Data').item.json.scanTimestamp).toLocaleString()
        }
      ]
    },
    {
      "type": "paragraph",
      "content": [
        {
          "type": "text",
          "text": "📊 Summary:"
        }
      ]
    },
    {
      "type": "bulletList",
      "content": [
        {
          "type": "listItem",
          "content": [
            {
              "type": "paragraph",
              "content": [
                {
                  "type": "text",
                  "text": "🔴 High/Critical: " + $('Process SAST Data').item.json.highSeverity
                }
              ]
            }
          ]
        },
        {
          "type": "listItem",
          "content": [
            {
              "type": "paragraph",
              "content": [
                {
                  "type": "text",
                  "text": "🟡 Medium: " + $('Process SAST Data').item.json.mediumSeverity
                }
              ]
            }
          ]
        },
        {
          "type": "listItem",
          "content": [
            {
              "type": "paragraph",
              "content": [
                {
                  "type": "text",
                  "text": "🟢 Low: " + $('Process SAST Data').item.json.lowSeverity
                }
              ]
            }
          ]
        },
        {
          "type": "listItem",
          "content": [
            {
              "type": "paragraph",
              "content": [
                {
                  "type": "text",
                  "text": "📋 Total Issues: " + $('Process SAST Data').item.json.totalIssues
                }
              ]
            }
          ]
        }
      ]
    },
    {
      "type": "paragraph",
      "content": [
        {
          "type": "text",
          "text": $('Process SAST Data').item.json.highSeverity > 0 ? "⚠️ Action Required: High/Critical vulnerabilities found. Please review immediately." : "✅ No critical vulnerabilities detected."
        }
      ]
    }
  ]
} }}

=[{
  "contentType": "application/vnd.microsoft.card.adaptive",
  "content": {
    "type": "AdaptiveCard",
    "version": "1.0",
    "body": [
      {
        "type": "TextBlock",
        "text": "🚨 Critical Security Alert",
        "weight": "Bolder",
        "size": "Large",
        "color": "Attention"
      },
      {
        "type": "TextBlock",
        "text": "High severity vulnerabilities detected in " + $('Process SAST Data').item.json.projectKey,
        "wrap": true
      },
      {
        "type": "FactSet",
        "facts": [
          {
            "title": "Scanner",
            "value": $('Process SAST Data').item.json.scanTool
          },
          {
            "title": "Critical/High",
            "value": $('Process SAST Data').item.json.highSeverity.toString()
          },
          {
            "title": "Medium",
            "value": $('Process SAST Data').item.json.mediumSeverity.toString()
          },
          {
            "title": "Total Issues",
            "value": $('Process SAST Data').item.json.totalIssues.toString()
          },
          {
            "title": "Scan Time",
            "value": new Date($('Process SAST Data').item.json.scanTimestamp).toLocaleString()
          }
        ]
      }
    ],
    "actions": [
      {
        "type": "Action.OpenUrl",
        "title": "View in Jira",
        "url": $vars.JIRA_BASE_URL + "/browse/" + $('Find Security Tasks').item.json.issues[0].key
      }
    ]
  }
}]

=[{
  "contentType": "application/vnd.microsoft.card.adaptive",
  "content": {
    "type": "AdaptiveCard",
    "version": "1.0",
    "body": [
      {
        "type": "TextBlock",
        "text": "✅ Security Review Passed",
        "weight": "Bolder",
        "size": "Large",
        "color": "Good"
      },
      {
        "type": "TextBlock",
        "text": "Security scan completed successfully for " + $('Process SAST Data').item.json.projectKey,
        "wrap": true
      },
      {
        "type": "FactSet",
        "facts": [
          {
            "title": "Scanner",
            "value": $('Process SAST Data').item.json.scanTool
          },
          {
            "title": "Issues Found",
            "value": $('Process SAST Data').item.json.totalIssues.toString()
          },
          {
            "title": "Status",
            "value": "Auto-approved ✅"
          },
          {
            "title": "Scan Time",
            "value": new Date($('Process SAST Data').item.json.scanTimestamp).toLocaleString()
          }
        ]
      }
    ]
  }
}]
